"https://jinja-net.jp/jinja-all/jsearch3all.php?jinjya=12892","source_type":"shrine_association","field_name":"shrine_information","notes":"神社名・所在地・由緒・御祭神の確認に使用。未確認の情報は記載していません。"},{"name":"座標参照・地図情報","url":"https://geocode.arcgis.com/arcgis/rest/services/World/GeocodeServer/findAddressCandidates","source_type":"other","field_name":"coordinates","notes":"住所・自治体と座標を照合し、地図上の位置確認に使用。"}]},{"name":"藤崎八旛宮","slug":"fujisaki-hachi-miya","prefecture":"熊本県","prefecture_slug":"kumamoto","municipality":"熊本市","address":"熊本県熊本市井川渕町3-1","latitude":32.808308705,"longitude":130.718622028,"official_url":null,"history":"藤崎八旛宮は、承平５年（９３５）朱雀天皇の勅願によって、山城国（京都）の石清水八幡宮を、国家の鎮護として茶臼山（今の藤崎台球場）に勧請されたのが始まりである。鎮座の日、勅使が藤の鞭を地中に挿したところ、芽を吹き枝葉が栄えたので、藤崎宮の名称が起ったと伝えられていると伝えられています。伝承には諸説あります。","deities":["応神天皇"],"benefits":[],"lineages":["八幡信仰"],"sources":[{"name":"皇學館大学・県神社庁協力「新全国神社検索」","url":"https://jinja-net.jp/jinja-all/jsearch3all.php?jinjya=8062","source_type":"shrine_association","field_name":"shrine_information","notes":"神社名・所在地・由緒・御祭神の確認に使用。未確認の情報は記載していません。"},{"name":"座標参照・地図情報","url":"https://geocode.arcgis.com/arcgis/rest/services/World/GeocodeServer/findAddressCandidates","source_type":"other","field_name":"coordinates","notes":"住所・自治体と座標を照合し、地図上の位置確認に使用。"}]},{"name":"宇佐神宮","slug":"usa-jingu","prefecture":"大分県","prefecture_slug":"oita","municipality":"宇佐市","address":"大分県宇佐市大字南宇佐2859番地","latitude":33.52348141,"longitude":131.377165597,"official_url":null,"history":"神武東征 まず社名について。奈良時代にはただ八幡宮・八幡神宮・八幡神社 八幡大菩薩宮等と呼ばれていたが、平安時代に京都に石清水八幡宮が創建されてからは、石清水八幡宮と区別する意味で宇佐宮・八幡宇佐宮・宇佐八幡宮と云うように「宇佐」の字をつけるようになったと伝えられています。伝承には諸説あります。","deities":["応神天皇","多岐津姫命","市杵島姫命","多紀理姫命","神功皇后"],"benefits":[],"lineages":["八幡信仰","宗像信仰"],"sources":[{"name":"皇學館大学・県神社庁協力「新全国神社検索」","url":"https://jinja-net.jp/jinja-all/jsearch3all.php?jinjya=7976","source_type":"shrine_association","field_name":"shrine_information","notes":"神社名・所在地・由緒・御祭神の確認に使用。未確認の情報は記載していません。"},{"name":"座標参照・地図情報","url":"https://geocode.arcgis.com/arcgis/rest/services/World/GeocodeServer/findAddressCandidates","source_type":"other","field_name":"coordinates","notes":"住所・自治体と座標を照合し、地図上の位置確認に使用。"}]},{"name":"柞原八幡宮","slug":"kubara-hachimangu","prefecture":"大分県","prefecture_slug":"oita","municipality":"大分市","address":"大分県大分市大字八幡987番地","latitude":33.238340564,"longitude":131.551001018,"official_url":null,"history":"社号 柞原八幡宮（ユスハラハチマングウ） 大正５年（１９１６）、国幣小社に昇格。創建 天長４年（８２７）、延暦寺の名僧・金亀和尚が宇佐神宮の参篭にて神告を蒙り柞原山に勧請したのを、当宮の創建の起原とすると伝えられています。伝承には諸説あります。","deities":["応神天皇","仲哀天皇","神功皇后"],"benefits":[],"lineages":["八幡信仰"],"sources":[{"name":"皇學館大学・県神社庁協力「新全国神社検索」","url":"https://jinja-net.jp/jinja-all/jsearch3all.php?jinjya=7988","source_type":"shrine_association","field_name":"shrine_information","notes":"神社名・所在地・由緒・御祭神の確認に使用。未確認の情報は記載していません。"},{"name":"座標参照・地図情報","url":"https://geocode.arcgis.com/arcgis/rest/services/World/GeocodeServer/findAddressCandidates","source_type":"other","field_name":"coordinates","notes":"住所・自治体と座標を照合し、地図上の位置確認に使用。"}]},{"name":"西寒多神社","slug":"nishi-samu-ta-jinja","prefecture":"大分県","prefecture_slug":"oita","municipality":"大分市","address":"大分県大分市大字寒田1644番地","latitude":33.172734392,"longitude":131.598409255,"official_url":null,"history":"創祀は遠く応神天皇９年西暦２７８年４月に武内宿禰勅命を奉じて西寒多山上に宮殿を建立すとあり。延喜式内の大社として国司をはじめ武将の信仰あつく、とくに大友能直公、宗麟公をはじめ代々の尊崇厚く、応永１５年（１４０８）３月、大友親世公社殿を現在地にうつし、家内安全、婚姻、学業、農業、食物、厄除、交通安全、消防の守り神として国民の崇敬いよいよ深く、明治４年５月１４日、国幣中社に列格、豊後の国の一の宮として皇室及び国家の優遇をうけ宝物として宗麟愛用の印章４個、大友能直、織田信長、豊臣秀吉、徳川家康の古文書を有し、現在別表神社として尊崇をあつめていると伝えられています。伝承には諸説あります。","deities":["西寒多大神"],"benefits":[],"lineages":[],"sources":[{"name":"皇學館大学・県神社庁協力「新全国神社検索」","url":"https://jinja-net.jp/jinja-all/jsearch3all.php?jinjya=7987","source_type":"shrine_association","field_name":"shrine_information","notes":"神社名・所在地・由緒・御祭神の確認に使用。未確認の情報は記載していません。"},{"name":"座標参照・地図情報","url":"https://geocode.arcgis.com/arcgis/rest/services/World/GeocodeServer/findAddressCandidates","source_type":"other","field_name":"coordinates","notes":"住所・自治体と座標を照合し、地図上の位置確認に使用。"}]},{"name":"八幡朝見神社","slug":"yahata-choken-jinja","prefecture":"大分県","prefecture_slug":"oita","municipality":"別府市","address":"大分県別府市朝見2丁目15番19号","latitude":33.271593584,"longitude":131.495061496,"official_url":null,"history":"別府温泉の守護神 八幡朝見神社 由緒 朝見八幡宮勧請由来記によればその御鎮座は、実に建久７丙辰年（１１９６）１０月まで遡る。豊前・豊後守護職、大友能直公は入国するや直ちに鎌倉幕府の鎮守、鶴ヶ岡八幡宮の御勧請を志し、建久７年朔日、家臣能登之助国久に命じ、朝見庄民をして、龍ヶ岡（現在の乙原）の地に御勧請申し上げたと伝えられています。伝承には諸説あります。","deities":["大鷦鷯尊"],"benefits":[],"lineages":[],"sources":[{"name":"皇學館大学・県神社庁協力「新全国神社検索」","url":"https://jinja-net.jp/jinja-all/jsearch3all.php?jinjya=8048","source_type":"shrine_association","field_name":"shrine_information","notes":"神社名・所在地・由緒・御祭神の確認に使用。未確認の情報は記載していません。"},{"name":"座標参照・地図情報","url":"https://geocode.arcgis.com/arcgis/rest/services/World/GeocodeServer/findAddressCandidates","source_type":"other","field_name":"coordinates","notes":"住所・自治体と座標を照合し、地図上の位置確認に使用。"}]},{"name":"宮崎神宮","slug":"miyazaki-jingu","prefecture":"宮崎県","prefecture_slug":"miyazaki","municipality":"宮崎市","address":"宮崎県宮崎市神宮2-4-1","latitude":31.938465522,"longitude":131.423482069,"official_url":null,"history":"神武東征 神武天皇は大御名を神日本磐余彦尊御名を狭野命と申し上げました。天照大御神から五代目の御孫に当らせられますと伝えられています。伝承には諸説あります。","deities":["神日本磐余彦天皇"],"benefits":[],"lineages":[],"sources":[{"name":"皇學館大学・県神社庁協力「新全国神社検索」","url":"https://jinja-net.jp/jinja-all/jsearch3all.php?jinjya=8359","source_type":"shrine_association","field_name":"shrine_information","notes":"神社名・所在地・由緒・御祭神の確認に使用。未確認の情報は記載していません。"},{"name":"座標参照・地図情報","url":"https://geocode.arcgis.com/arcgis/rest/services/World/GeocodeServer/findAddressCandidates","source_type":"other","field_name":"coordinates","notes":"住所・自治体と座標を照合し、地図上の位置確認に使用。"}]},{"name":"青島神社","slug":"chintao-jinja","prefecture":"宮崎県","prefecture_slug":"miyazaki","municipality":"宮崎市","address":"宮崎県宮崎市青島2-13-1","latitude":31.804592888,"longitude":131.474933389,"official_url":null,"history":"天孫瓊々杵命の皇子彦火火出見命が、海積宮から御還幸の際の御宮居の跡として三神を奉祀し御神威を今日に伝えている。奉祀の年代は明らかでないが、国司巡視記「日向土産」（平安朝）に「嵯峨天皇の御宇奉崇青島大明神」と記されてあったといわれ（約千百八十年前）、文亀（室町時代・約四百八十九年前）以降は、藩主伊東家の崇敬厚く、社殿の改築、境内の保全に力を尽し、明治以後は御祭神の御威霊を仰ぎ熱帯植物繁茂する国内絶無の霊域をたずねる人々いよいよ多く、縁結・安産・航海・交通安全の神として、御神威は益々輝き今日に至っていると伝えられています。伝承には諸説あります。","deities":["彦火火出見命","豊玉姫命","塩筒大神"],"benefits":[],"lineages":[],"sources":[{"name":"皇學館大学・県神社庁協力「新全国神社検索」","url":"https://jinja-net.jp/jinja-all/jsearch3all.php?jinjya=8381","source_type":"shrine_association","field_name":"shrine_information","notes":"神社名・所在地・由緒・御祭神の確認に使用。未確認の情報は記載していません。"},{"name":"座標参照・地図情報","url":"https://geocode.arcgis.com/arcgis/rest/services/World/GeocodeServer/findAddressCandidates","source_type":"other","field_name":"coordinates","notes":"住所・自治体と座標を照合し、地図上の位置確認に使用。"}]},{"name":"鵜戸神宮","slug":"u-to-jingu","prefecture":"宮崎県","prefecture_slug":"miyazaki","municipality":"日南市","address":"宮崎県日南市大字宮浦3232","latitude":31.650728402,"longitude":131.466709398,"official_url":null,"history":"当神宮は、「鵜戸さん」と愛称され、国定公園日南海岸の風光明媚な所、日南市鵜戸山の日向灘に面した、自然の神秘な洞窟の内に、朱塗の色あざやかにご鎮座されている。この洞窟は、主祭神の産殿の址と伝えられる霊地で、およそ千平方メートル（約三百坪）ほどの広さがあると伝えられています。伝承には諸説あります。","deities":[],"benefits":[],"lineages":[],"sources":[{"name":"皇學館大学・県神社庁協力「新全国神社検索」","url":"https://jinja-net.jp/jinja-all/jsearch3all.php?jinjya=8429","source_type":"shrine_association","field_name":"shrine_information","notes":"神社名・所在地・由緒・御祭神の確認に使用。未確認の情報は記載していません。"},{"name":"座標参照・地図情報","url":"https://geocode.arcgis.com/arcgis/rest/services/World/GeocodeServer/findAddressCandidates","source_type":"other","field_name":"coordinates","notes":"住所・自治体と座標を照合し、地図上の位置確認に使用。"}]},{"name":"都農神社","slug":"tsuno-jinja","prefecture":"宮崎県","prefecture_slug":"miyazaki","municipality":"児湯郡都農町","address":"宮崎県児湯郡都農町大字川北13294","latitude":32.263216904,"longitude":131.558647022,"official_url":null,"history":"都農神社は古来日向国一之と称え、御祭神は御神徳の高い大己貴命（又の御名大国主命）を奉斎する古社であります。当社の縁起によれば、神武天皇御東遷の砌、宮崎の宮を御進発になり、途中此の地において国土平安、海上平穏、武運長久を御祈念の為、御親ら鎮祭されたのを当社の創祀と伝えますと伝えられています。伝承には諸説あります。","deities":["大己貴命"],"benefits":[],"lineages":["出雲系信仰"],"sources":[{"name":"皇學館大学・県神社庁協力「新全国神社検索」","url":"https://jinja-net.jp/jinja-all/jsearch3all.php?jinjya=8475","source_type":"shrine_association","field_name":"shrine_information","notes":"神社名・所在地・由緒・御祭神の確認に使用。未確認の情報は記載していません。"},{"name":"座標参照・地図情報","url":"https://geocode.arcgis.com/arcgis/rest/services/World/GeocodeServer/findAddressCandidates","source_type":"other","field_name":"coordinates","notes":"住所・自治体と座標を照合し、地図上の位置確認に使用。"}]},{"name":"霧島神宮","slug":"kirishima-jingu","prefecture":"鹿児島県","prefecture_slug":"kagoshima","municipality":"霧島市","address":"鹿児島県霧島市霧島田口2608-5","latitude":31.858931439,"longitude":130.871733377,"official_url":null,"history":"秋祭 当神宮は天祖天照大神の御神勅を畏み戴きて三種の神器（皇位の御璽）を奉持し高千穂峰に天降りまして皇基を建て給うた肇国の祖神＜天孫瓊瓊杵尊＞をお祀りしているお社です。旧記によると欽明天皇の御宇（西暦５４０）、はじめ高千穂峰のほど近く脊門丘に社殿が建立されたが、その後たびたび噴火炎上し幾星霜を経て今から５００年前現在の社地へ御鎮座になりましたと伝えられています。伝承には諸説あります。","deities":["天饒石国饒石天津日高彦火瓊瓊杵尊"],"benefits":[],"lineages":[],"sources":[{"name":"皇學館大学・県神社庁協力「新全国神社検索」","url":"https://jinja-net.jp/jinja-all/jsearch3all.php?jinjya=8621","source_type":"shrine_association","field_name":"shrine_information","notes":"神社名・所在地・由緒・御祭神の確認に使用。未確認の情報は記載していません。"},{"name":"座標参照・地図情報","url":"https://geocode.arcgis.com/arcgis/rest/services/World/GeocodeServer/findAddressCandidates","source_type":"other","field_name":"coordinates","notes":"住所・自治体と座標を照合し、地図上の位置確認に使用。"}]},{"name":"鹿児島神宮","slug":"kagoshima-jingu","prefecture":"鹿児島県","prefecture_slug":"kagoshima","municipality":"霧島市","address":"鹿児島県霧島市隼人町内2496-ロ","latitude":31.753680343,"longitude":130.737839062,"official_url":null,"history":"鹿児島神宮の創祀は遠く神代にあって、又皇孫神武天皇の御代なりとも伝えられます。御祭神彦穂穂出見尊は筑紫の国開拓の祖神に坐しましこの地に高千穂宮（皇居）を営み給い、５８０歳の長寿に亘らせらるる間農耕畜産漁猟の道を指導し民政安定の基礎をつくり給うたのであると伝えられています。伝承には諸説あります。","deities":["天津日高彦穂穂出見尊","豊玉比売命"],"benefits":[],"lineages":[],"sources":[{"name":"皇學館大学・県神社庁協力「新全国神社検索」","url":"https://jinja-net.jp/jinja-all/jsearch3all.php?jinjya=8622","source_type":"shrine_association","field_name":"shrine_information","notes":"神社名・所在地・由緒・御祭神の確認に使用。未確認の情報は記載していません。"},{"name":"座標参照・地図情報","url":"https://geocode.arcgis.com/arcgis/rest/services/World/GeocodeServer/findAddressCandidates","source_type":"other","field_name":"coordinates","notes":"住所・自治体と座標を照合し、地図上の位置確認に使用。"}]},{"name":"新田神社","slug":"nitta-jinja","prefecture":"鹿児島県","prefecture_slug":"kagoshima","municipality":"薩摩川内市","address":"鹿児島県薩摩川内市宮内町1935-2","latitude":31.827632,"longitude":130.292855,"official_url":null,"history":"当神社は神亀山上に鎮りまして其の創祀の年月は詳ならずと雖も所伝永万元年の古文書に「当宮自再興経３００余歳云々」とあれば貞観の昔に再興ありし事明らかである。（三国神社伝記に聖武天皇神亀二年創立云々ともある）旧薩藩唯一の大社にして社録高８６７石を寄進され皇室代々の御崇敬厚く又島津氏封を薩摩国に受けし以来薩摩国一の宮として藩内の首社に列し社殿の結構壮麗輪かんの美をなすと伝えられています。伝承には諸説あります。","deities":["天津彦彦火瓊瓊杵尊"],"benefits":[],"lineages":[],"sources":[{"name":"皇學館大学・県神社庁協力「新全国神社検索」","url":"https://jinja-net.jp/jinja-all/jsearch3all.php?jinjya=8587","source_type":"shrine_association","field_name":"shrine_information","notes":"神社名・所在地・由緒・御祭神の確認に使用。未確認の情報は記載していません。"},{"name":"座標参照・地図情報","url":"https://www.openstreetmap.org/way/1412944967","source_type":"other","field_name":"coordinates","notes":"住所・自治体と座標を照合し、地図上の位置確認に使用。"}]},{"name":"住吉神社","slug":"sumiyoshi-jinja-fukuoka","prefecture":"福岡県","prefecture_slug":"fukuoka","municipality":"福岡市","address":"福岡県福岡市博多区住吉3-1-51","latitude":33.5857544,"longitude":130.4134348,"official_url":null,"history":"住吉三神は遠い神代の昔に、伊弉諾大神が筑紫の日向の橘の小戸の阿波伎原でミソギハラへ（禊祓）をされた時に、志賀島神社の御祭神・ワタツミ三神と警固神社の御祭神・直毘の神と共に御出現になりました。したがって当社の御鎮座は遠い神代のことで、年代を定めることは出来ませんが、全国的にも九州でも最も古いお宮様の一つですと伝えられています。伝承には諸説あります。","deities":["底筒男命","中筒男命","表筒男命"],"benefits":[],"lineages":["住吉信仰"],"sources":[{"name":"皇學館大学・県神社庁協力「新全国神社検索」","url":"https://jinja-net.jp/jinja-all/jsearch3all.php?jinjya=7481","source_type":"shrine_association","field_name":"shrine_information","notes":"神社名・所在地・由緒・御祭神の確認に使用。未確認の情報は記載していません。"},{"name":"座標参照・地図情報","url":"https://www.openstreetmap.org/way/45779271","source_type":"other","field_name":"coordinates","notes":"住所・自治体と座標を照合し、地図上の位置確認に使用。"}]},{"name":"健軍神社","slug":"kengun-jinja","prefecture":"熊本県","prefecture_slug":"kumamoto","municipality":"熊本市","address":"熊本県熊本市健軍本町13-1","latitude":32.7848444,"longitude":130.755211,"official_url":null,"history":null,"deities":["健緒組命","健磐龍命","阿蘇都比売命"],"benefits":[],"lineages":[],"sources":[{"name":"皇學館大学・県神社庁協力「新全国神社検索」","url":"https://jinja-net.jp/jinja-all/jsearch3all.php?jinjya=8099","source_type":"shrine_association","field_name":"shrine_information","notes":"神社名・所在地・由緒・御祭神の確認に使用。未確認の情報は記載していません。"},{"name":"座標参照・地図情報","url":"https://www.openstreetmap.org/way/410981804","source_type":"other","field_name":"coordinates","notes":"住所・自治体と座標を照合し、地図上の位置確認に使用。"}]},{"name":"枚聞神社","slug":"mai-jinja","prefecture":"鹿児島県","prefecture_slug":"kagoshima","municipality":"指宿市","address":"鹿児島県指宿市開聞十町1366","latitude":31.2078734,"longitude":130.5397714,"official_url":null,"history":"祭神 大日・貴命（天照大御神）を正祀とし、他に皇祖神八柱神を併せ祀るとあり。神社の沿革 御鎮座年代を詳らかにせずといえども、社伝には遠く神代の創祀なりと伝うと伝えられています。伝承には諸説あります。","deities":[],"benefits":[],"lineages":[],"sources":[{"name":"皇學館大学・県神社庁協力「新全国神社検索」","url":"https://jinja-net.jp/jinja-all/jsearch3all.php?jinjya=8568","source_type":"shrine_association","field_name":"shrine_information","notes":"神社名・所在地・由緒・御祭神の確認に使用。未確認の情報は記載していません。"},{"name":"座標参照・地図情報","url":"https://www.openstreetmap.org/way/743827330","source_type":"other","field_name":"coordinates","notes":"住所・自治体と座標を照合し、地図上の位置確認に使用。"}]},{"name":"加藤神社","slug":"kato-jinja","prefecture":"熊本県","prefecture_slug":"kumamoto","municipality":"熊本市","address":"熊本県熊本市本丸2-1","latitude":32.8072411,"longitude":130.7051846,"official_url":null,"history":null,"deities":["加藤清正"],"benefits":[],"lineages":[],"sources":[{"name":"皇學館大学・県神社庁協力「新全国神社検索」","url":"https://jinja-net.jp/jinja-all/jsearch3all.php?jinjya=8863","source_type":"shrine_association","field_name":"shrine_information","notes":"神社名・所在地・由緒・御祭神の確認に使用。未確認の情報は記載していません。"},{"name":"座標参照・地図情報","url":"https://www.openstreetmap.org/way/660867654","source_type":"other","field_name":"coordinates","notes":"住所・自治体と座標を照合し、地図上の位置確認に使用。"}]}]$payload$::jsonb AS value), incoming AS (SELECT * FROM jsonb_to_recordset((SELECT value FROM payload)) AS x(name text,slug text,prefecture text,prefecture_slug text,municipality text,address text,latitude double precision,longitude double precision,official_url text,history text,deities text[],benefits text[],lineages text[],sources jsonb)), pref_upsert AS (INSERT INTO public.prefectures(name,slug) SELECT DISTINCT prefecture,prefecture_slug FROM incoming ON CONFLICT (slug) DO UPDATE SET name=excluded.name RETURNING id,name), municipality_upsert AS (INSERT INTO public.municipalities(prefecture_id,name) SELECT DISTINCT p.id,i.municipality FROM incoming i JOIN pref_upsert p ON p.name=i.prefecture ON CONFLICT (prefecture_id,name) DO UPDATE SET name=excluded.name RETURNING id,prefecture_id,name), shrine_upsert AS (INSERT INTO public.shrines(name,slug,prefecture_id,municipality_id,address,location,official_url,history,is_published) SELECT i.name,i.slug,p.id,m.id,i.address,ST_SetSRID(ST_MakePoint(i.longitude,i.latitude),4326)::geography,i.official_url,i.history,true FROM incoming i JOIN pref_upsert p ON p.name=i.prefecture JOIN municipality_upsert m ON m.prefecture_id=p.id AND m.name=i.municipality ON CONFLICT (slug) DO UPDATE SET name=excluded.name,prefecture_id=excluded.prefecture_id,municipality_id=excluded.municipality_id,address=excluded.address,location=excluded.location,official_url=COALESCE(excluded.official_url,public.shrines.official_url),history=COALESCE(excluded.history,public.shrines.history),is_published=true,updated_at=now() RETURNING id,slug), source_rows AS (SELECT DISTINCT i.slug,s.name,s.url,s.source_type,s.field_name,s.notes FROM incoming i CROSS JOIN LATERAL jsonb_to_recordset(i.sources) AS s(name text,url text,source_type text,field_name text,notes text) WHERE s.url IS NOT NULL), source_upsert AS (INSERT INTO public.sources(name,url,source_type,last_verified_at,notes) SELECT s.name,s.url,s.source_type::public.source_type,DATE '2026-10-01',s.notes FROM (SELECT DISTINCT name,url,source_type,notes FROM source_rows) s WHERE NOT EXISTS (SELECT 1 FROM public.sources old WHERE old.name=s.name AND old.url=s.url) RETURNING id,name,url), source_records AS (SELECT id,name,url FROM source_upsert UNION ALL SELECT old.id,old.name,old.url FROM public.sources old JOIN (SELECT DISTINCT name,url FROM source_rows) x ON x.name=old.name AND x.url=old.url), source_links AS (INSERT INTO public.shrine_sources(shrine_id,source_id,field_name) SELECT DISTINCT sh.id,src.id,s.field_name FROM source_rows s JOIN shrine_upsert sh ON sh.slug=s.slug JOIN source_records src ON src.name=s.name AND src.url=s.url ON CONFLICT (shrine_id,source_id) DO UPDATE SET field_name=COALESCE(excluded.field_name,public.shrine_sources.field_name) RETURNING shrine_id), deity_links AS (INSERT INTO public.shrine_deities(shrine_id,deity_id,role,display_order) SELECT DISTINCT sh.id,d.id,'principal'::public.shrine_deity_role,0 FROM incoming i JOIN shrine_upsert sh ON sh.slug=i.slug CROSS JOIN LATERAL unnest(COALESCE(i.deities,ARRAY[]::text[])) raw(name) JOIN LATERAL (SELECT de.id FROM public.deities de WHERE de.name=raw.name OR raw.name=ANY(de.aliases) ORDER BY (de.name=raw.name) DESC,de.slug LIMIT 1) d ON true ON CONFLICT (shrine_id,deity_id) DO UPDATE SET role='principal'::public.shrine_deity_role RETURNING shrine_id,deity_id), shrine_lineage_links AS (INSERT INTO public.shrine_lineages(shrine_id,lineage_id) SELECT DISTINCT sh.id,l.id FROM incoming i JOIN shrine_upsert sh ON sh.slug=i.slug CROSS JOIN LATERAL unnest(COALESCE(i.lineages,ARRAY[]::text[])) ln(name) JOIN public.lineages l ON l.name=ln.name ON CONFLICT DO NOTHING RETURNING shrine_id,lineage_id), shrine_benefit_links AS (INSERT INTO public.shrine_benefits(shrine_id,benefit_id,description) SELECT DISTINCT sh.id,b.id,'出典に記された信仰上の願意の一例です。宗教的効能や結果を保証するものではありません。' FROM incoming i JOIN shrine_upsert sh ON sh.slug=i.slug CROSS JOIN LATERAL unnest(COALESCE(i.benefits,ARRAY[]::text[])) bn(name) JOIN public.benefits b ON b.name=bn.name ON CONFLICT (shrine_id,benefit_id) DO UPDATE SET description=excluded.description RETURNING shrine_id,benefit_id), inferred_deity_benefits AS (INSERT INTO public.deity_benefits(deity_id,benefit_id) SELECT DISTINCT dl.deity_id,sb.benefit_id FROM deity_links dl JOIN shrine_benefit_links sb ON sb.shrine_id=dl.shrine_id ON CONFLICT DO NOTHING RETURNING deity_id,benefit_id) SELECT jsonb_build_object('shrines_upserted',(SELECT count(*) FROM shrine_upsert),'sources_added',(SELECT count(*) FROM source_upsert),'source_links',(SELECT count(*) FROM source_links),'deity_links',(SELECT count(*) FROM deity_links),'lineage_links',(SELECT count(*) FROM shrine_lineage_links),'benefit_links',(SELECT count(*) FROM shrine_benefit_links),'deity_benefit_links',(SELECT count(*) FROM inferred_deity_benefits)) AS result;
